// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(bool asOwner) internal {
        uint256 balBefore = address(c).balance;
        try c.sudicideAnyone() {} catch { return; }
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == 0);
    }

    function testFuzz_run(bool asOwner) public {
        _run(asOwner);
    }

    receive() external payable {}
}
